import Foundation

// Coach page — the records it shows and their order. Every entry is one of the app's own Coach records (the
// rules-based adaptation engine). Nothing is sample text and nothing is generated by an AI model.

enum CyCoachAuthor: Equatable { case coach, athlete }

enum CyCoachEntryKind: String, Equatable {
    case observation, recommendation, recovery, question, answer, proposal, decision, outcome
    var label: String {
        switch self {
        case .observation: return "Observation"
        case .recommendation: return "Recommendation"
        case .recovery: return "Recovery"
        case .question: return "Question"
        case .answer: return "Answer"
        case .proposal: return "Needs your decision"
        case .decision: return "Your decision"
        case .outcome: return "Plan change"
        }
    }
    var icon: String {
        switch self {
        case .observation: return "eye"
        case .recommendation: return "lightbulb"
        case .recovery: return "bed.double"
        case .question: return "questionmark.bubble"
        case .answer: return "text.bubble"
        case .proposal: return "exclamationmark.bubble"
        case .decision: return "checkmark.circle"
        case .outcome: return "arrow.triangle.2.circlepath"
        }
    }
}

struct CyCoachEntry: Identifiable, Equatable {
    enum Opens: Equatable { case proposal(String), adjustments, hybrid(String), ftp }
    let id: String
    let at: Date
    let author: CyCoachAuthor
    let kind: CyCoachEntryKind
    let text: String
    var detail: String? = nil
    var opens: Opens? = nil
    /// What the independent policy check concluded about this proposal (shadow mode: it changes nothing).
    var check: String? = nil
    /// Who produced the line: "Rules", "You", "AI not connected".
    var chip: String? = nil
    var basedOn: [String] = []
}

/// Builds the timeline from the app's Coach records. Pure, so it is the same in Lab and production.
enum CoachTimeline {
    struct Input {
        var summary: AdaptationSummary?
        var proposals: [AdaptiveProposal]
        var applied: [PlanAdjustment]
        var accepted: [AppliedProposal]
        var now: Date
        /// Independent policy check per open proposal (AdaptiveProposal.id → sentence).
        var checks: [String: String] = [:]
        /// Proposals the athlete has answered, from the durable decision history.
        var closed: [Closed] = []
        /// The conversation, as stored.
        var chat: [CoachChatMessage] = []
        /// The one item the Home card and the Plan row are showing now (Store.homeCoach). When it is not already one of
        /// the records above it is listed too, so the three places never disagree.
        var current: HomeCoachItem? = nil
    }

    /// The Home / Plan item as a timeline entry. nil when the timeline already holds it (a proposal of the adaptation
    /// engine, an applied change). A proposal of the hybrid coach keeps its own approval sheet; the FTP suggestion keeps
    /// its own sheet; a finding, an insight or the rating prompt is a note with no decision.
    static func currentEntry(_ c: HomeCoachItem, at: Date) -> CyCoachEntry? {
        switch c.source {
        case .adaptiveProposal, .adjustment: return nil
        case .hybridProposal(let id): return CyCoachEntry(id: "hyb-\(id)", at: at, author: .coach, kind: .proposal, text: c.plainTitle, detail: c.evidence, opens: .hybrid(id))
        case .ftp: return CyCoachEntry(id: "ftp", at: at, author: .coach, kind: .recommendation, text: c.plainTitle, detail: c.evidence, opens: .ftp)
        case .gap: return CyCoachEntry(id: "now-gap", at: at, author: .coach, kind: .observation, text: c.plainTitle, detail: c.evidence)
        case .revise, .insight, .rate: return CyCoachEntry(id: "now-note", at: at, author: .coach, kind: .recommendation, text: c.plainTitle, detail: c.evidence)
        }
    }
    /// One answered proposal: what was proposed, the check, and the athlete's decision with its time.
    struct Closed: Equatable {
        var id: String
        var at: Date
        var text: String
        var why: String
        var approved: Bool
        var check: String?
    }

    static func entries(_ i: Input) -> [CyCoachEntry] {
        var out: [CyCoachEntry] = []
        if let s = i.summary {
            for (n, f) in s.findings.enumerated() {
                out.append(CyCoachEntry(id: "obs-\(n)", at: s.at, author: .coach, kind: .observation, text: f))
            }
            if let p = s.painAdvice { out.append(CyCoachEntry(id: "pain", at: s.at, author: .coach, kind: .recovery, text: p, opens: .adjustments)) }
            if let q = s.feedbackRequest { out.append(CyCoachEntry(id: "ask", at: s.at, author: .coach, kind: .question, text: q)) }
        }
        for a in i.accepted {
            out.append(CyCoachEntry(id: "acc-\(a.id)", at: a.appliedAt, author: .athlete, kind: .decision, text: "Approved: \(a.text)"))
        }
        for a in i.applied {
            out.append(CyCoachEntry(id: "adj-\(a.id)", at: a.createdAt, author: .coach, kind: .outcome, text: a.summary, detail: a.why, opens: .adjustments))
        }
        // A proposal has no time of its own: it stands at the analysis that raised it (or now, if none is stored).
        let raised = i.summary?.at ?? i.now
        for p in i.proposals {
            out.append(CyCoachEntry(id: "prop-\(p.id)", at: raised, author: .coach, kind: p.adjustments.isEmpty ? .recommendation : .proposal,
                                    text: p.text, detail: p.why, opens: .proposal(p.id), check: i.checks[p.id]))
        }
        if let c = i.current, let e = currentEntry(c, at: raised) { out.append(e) }
        for c in i.closed {
            out.append(CyCoachEntry(id: "closed-\(c.id)", at: c.at, author: .athlete, kind: .decision, text: "\(c.approved ? "Approved" : "Declined"): \(c.text)",
                                    detail: c.why, check: c.check, chip: CoachSource.athlete.chip))
        }
        for m in i.chat {
            out.append(CyCoachEntry(id: "chat-\(m.id.uuidString)", at: m.at, author: m.source == .athlete ? .athlete : .coach, kind: m.source == .athlete ? .question : .answer,
                                    text: m.text, chip: m.source.chip, basedOn: m.basedOn))
        }
        // Oldest first; records of the same moment keep the order above (what was seen, then what is asked).
        return out.enumerated().sorted { ($0.element.at, $0.offset) < ($1.element.at, $1.offset) }.map(\.element)
    }

    static func dayText(_ d: Date, _ calendar: Calendar) -> String {
        let f = DateFormatter(); f.calendar = calendar; f.timeZone = calendar.timeZone; f.locale = Locale(identifier: "en_GB"); f.dateFormat = "EEE d MMM"
        return f.string(from: d)
    }

    static func days(_ e: [CyCoachEntry], now: Date, calendar: Calendar = .current) -> [(day: String, entries: [CyCoachEntry])] {
        var out: [(day: String, entries: [CyCoachEntry])] = []
        var last: Date?
        for x in e {
            let d = calendar.startOfDay(for: x.at)
            if d == last, let i = out.indices.last { out[i].entries.append(x) } else {
                out.append((day: calendar.isDate(d, inSameDayAs: now) ? "Today · \(dayText(x.at, calendar))" : dayText(x.at, calendar), entries: [x]))
                last = d
            }
        }
        return out
    }
}
